@startuml

class WebPortal {
  +versionNumber : string
  +urlAddress : string
}

class Building {
  +id : string
  +name : string
  +energyClass : string
  +address : string
  +yearOfConstruction : int
}

class AdditionalEntry {
  +name : string
  +isPublic : boolean
}

class TextualInformation extends AdditionalEntry {}

class NumericalInformation extends AdditionalEntry {
  +value : float
  +unit : string
}

class Image {
  +fileName : string
}

class User {
  +userName : string
  +emailAddress : string
  +password : string
}

class Administrator extends User {
  +idCardNumber : string
}

class Comment {
  +text : string
}

class Visitor {
}

WebPortal "1" -- "*" Building : provides catalog of
WebPortal "1" -- "*" User : has
WebPortal "1" -- "*" Visitor : has
Building "1" *-- "*" AdditionalEntry : has
Building "1" *-- "*" Image : has
Building "1" -- "1" Image : profile photo
User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
Building "1" -- "*" Comment : has
Visitor "0..*" -- "*" Building : searches

@enduml

